mapper.select:
SELECT id FROM entitlement_grant
WHERE user_id = #{userId}
  AND status = 'ACTIVE'
  AND effective_from <= NOW(3)
  AND expires_at > NOW(3)
  AND available_credits >= 1
  AND application_id = #{applicationId}
  AND application_version = #{applicationVersion}
  AND BINARY model_version = BINARY #{modelVersion}
  AND BINARY image_size = BINARY #{imageSize}
  AND output_count = #{outputCount}
ORDER BY expires_at, id
LIMIT #{limit}

SELECT COUNT(*) FROM entitlement_grant
WHERE user_id = #{userId}
  AND application_id = #{applicationId}
  AND application_version = #{applicationVersion}
  AND BINARY model_version = BINARY #{modelVersion}
  AND BINARY image_size = BINARY #{imageSize}
  AND output_count = #{outputCount}

mapper.update:
UPDATE entitlement_grant
SET available_credits = available_credits - #{units},
    frozen_credits = frozen_credits + #{units}
WHERE id = #{id}
  AND status = 'ACTIVE'
  AND effective_from <= NOW(3)
  AND expires_at > NOW(3)
  AND available_credits >= #{units}

UPDATE entitlement_grant
SET frozen_credits = frozen_credits - #{units},
    consumed_credits = consumed_credits + #{units}
WHERE id = #{id} AND frozen_credits >= #{units}

UPDATE entitlement_grant
SET frozen_credits = frozen_credits - #{units},
    available_credits = available_credits + #{units}
WHERE id = #{id} AND frozen_credits >= #{units}

UPDATE entitlement_grant
SET frozen_credits = frozen_credits - #{units},
    expired_credits = expired_credits + #{units}
WHERE id = #{id} AND frozen_credits >= #{units}

